/// IMPORTANT: 'dest_flash' must be 256-byte aligned and 'srce_ram' must be 4-byte aligned ///

Iap_Status iap_sector_write (const void * const dest_flash , void * const srce_ram , Iap_Sector_Wr_Size const wr_size)
{
  static const UInt16 phy_size [] = { 256 , 512 , 1024 , 4096 } ;

  UInt32 results [2]          ;
  UInt32 command [5] = { 51 } ;

  command [1] = (UInt32) dest_flash  ;
  command [2] = (UInt32) srce_ram    ;
  command [3] = phy_size [wr_size]   ;
  command [4] = CPU_CLOCK_HZ / 1000  ; // In KHz

  iap_execute (command,results)   ;

  return (Iap_Status) results [0] ;
}

